        ax.legend(fontsize=8);xlabel='Mean ('+unit['a']+')';ylabel='A - B ('+unit['a']+')'
    else:x,y=col(xname),col(yname);xlabel=xname+' ('+unit[xname]+')';ylabel=yname+' ('+unit[yname]+')'
    if kind in ['line','area','roc','pr_curve','calibration']:
